public class Item { public string Id=Guid.NewGuid().ToString(); public string Date; public string OriginalDate=""; public string Name; public decimal Target=1; public string Unit="项"; public string Kpi=""; public bool Numeric; public bool Temporary; public bool Deleted; public bool Backlog; public string Note=""; }
public class Entry { public string Id=Guid.NewGuid().ToString(); public string Item; public string Date; public decimal Amount; }
public class Goal { public string Month; public string Name; public decimal Target; public bool Manual; public decimal Actual; public decimal Adjustment; }
public class Session { public string Date; public DateTime Start; public bool Closed; public bool Reminded; public DateTime? ReminderAt; }
public class Data { public int IconSet=2; public List<Item> Items=new List<Item>(); public List<Entry> Entries=new List<Entry>(); public List<Goal> Goals=new List<Goal>(); public List<Session> Sessions=new List<Session>(); public Dictionary<string,string> Days=new Dictionary<string,string>(); public int X=-1; public int Y=-1; }
public class PixelButton : Button {
 bool hovered;
 public PixelButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
 protected override void OnMouseEnter(EventArgs e){hovered=true;Invalidate();base.OnMouseEnter(e);}
 protected override void OnMouseLeave(EventArgs e){hovered=false;Invalidate();base.OnMouseLeave(e);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Parent==null?BackColor:Parent.BackColor);Color fill=hovered?ForeColor:BackColor;Color text=hovered?BackColor:ForeColor;using(var b=new SolidBrush(fill)){g.FillRectangle(b,2,0,Width-4,Height);g.FillRectangle(b,0,2,Width,Height-4);}using(var p=new Pen(ForeColor)){g.DrawLine(p,2,0,Width-3,0);g.DrawLine(p,2,Height-1,Width-3,Height-1);g.DrawLine(p,0,2,0,Height-3);g.DrawLine(p,Width-1,2,Width-1,Height-3);}TextRenderer.DrawText(g,Text,Font,ClientRectangle,text,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);if(Focused)ControlPaint.DrawFocusRectangle(g,new Rectangle(3,3,Width-6,Height-6),text,fill);}
}
public class PixelProgress : Control {
 int val;public int Value{get{return val;}set{val=value;Invalidate();}}
 public PixelProgress(){DoubleBuffered=true;}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Color.FromArgb(29,34,34));int blocks=(Width-8)/8;int filled=(int)Math.Round(blocks*Math.Min(100,Math.Max(0,val))/100.0);for(int n=0;n<blocks;n++)using(var b=new SolidBrush(n<filled?Color.FromArgb(218,255,34):Color.FromArgb(64,69,59)))g.FillRectangle(b,4+n*8,4,6,Height-8);}
}
