 Button Button(string text,Action action){var b=new PixelButton{Text=text,FlatStyle=FlatStyle.Flat,BackColor=ink,ForeColor=lime,Height=28,Width=78,Margin=new Padding(3),Cursor=Cursors.Hand,Font=new Font("Microsoft YaHei UI",8,FontStyle.Bold)};b.FlatAppearance.BorderColor=Color.FromArgb(105,111,96);b.Click+=(s,e)=>action();return b;}
 void Save(){data.X=Left;data.Y=Top;var bytes=Json.Serialize(data);string temp=FileName+".tmp";System.IO.File.WriteAllText(temp,bytes,System.Text.Encoding.UTF8);if(System.IO.File.Exists(FileName)){string backup=Path.Combine(Dir,"backup-"+Today+".json");if(!System.IO.File.Exists(backup))File.Copy(FileName,backup);File.Replace(temp,FileName,null);}else File.Move(temp,FileName);}
 decimal Done(Item i){return data.Entries.Where(e=>e.Item==i.Id).Sum(e=>e.Amount);}
 string RemainingTitle(Item i){if(!i.Numeric)return i.Name;var match=Regex.Match(i.Name,@"(?<number>\d+(?:\.\d+)?)\s*(篇|封|个|条|次|份|页|人|项)");if(!match.Success)return i.Name;var number=match.Groups["number"];return i.Name.Substring(0,number.Index)+Math.Max(0,i.Target-Done(i)).ToString("0.##",System.Globalization.CultureInfo.InvariantCulture)+i.Name.Substring(number.Index+number.Length);}
 static bool ReminderWindowOpen(Session value,DateTime now){DateTime end=LocalStart(value).AddHours(9);return !value.Closed&&value.Date==now.ToString("yyyy-MM-dd")&&now>=end.AddMinutes(-30)&&now<end;}
 static bool ReminderDue(Session value,DateTime now){return !value.Reminded&&ReminderWindowOpen(value,now);}
 static DateTime LocalStart(Session value){return value.Start.Kind==DateTimeKind.Utc?value.Start.ToLocalTime():value.Start;}
 void Tick(){bool changed=false;foreach(var premature in data.Sessions.Where(s=>s.Date==Today&&s.Closed&&DateTime.Now<LocalStart(s).AddHours(9))){premature.Closed=false;foreach(var item in data.Items.Where(i=>i.Date==Today&&i.Backlog))item.Backlog=false;changed=true;}foreach(var old in data.Sessions.Where(s=>!s.Closed&&(s.Date!=Today||DateTime.Now>=LocalStart(s).AddHours(9))).ToList()){old.Closed=true;foreach(var i in data.Items.Where(i=>i.Date==old.Date&&!i.Deleted&&Done(i)<i.Target))i.Backlog=true;changed=true;}
 foreach(var i in data.Items.Where(i=>String.CompareOrdinal(i.Date,Today)<0&&!i.Deleted&&!i.Backlog&&Done(i)<i.Target)){i.Backlog=true;changed=true;}
 session=data.Sessions.FirstOrDefault(s=>s.Date==Today);if(session==null){session=new Session{Date=Today,Start=DateTime.Now};data.Sessions.Add(session);changed=true;}
 if(DateTime.Now<LocalStart(session).AddHours(8.5)&&(session.Reminded||session.ReminderAt.HasValue)){session.Reminded=false;session.ReminderAt=null;if(reminder!=null&&!reminder.IsDisposed)reminder.Close();changed=true;}
 var elapsed=DateTime.Now-LocalStart(session);clock.Text=session.Closed?"今日已收尾 · 可继续记录":elapsed.TotalHours<6?"已工作 "+elapsed.ToString(@"hh\:mm\:ss"):"距离下班 "+(LocalStart(session).AddHours(9)-DateTime.Now).ToString(@"hh\:mm\:ss");
 if(ReminderDue(session,DateTime.Now)&&DayType(DateTime.Today)!="休息"){session.Reminded=true;ShowReminder();changed=true;}
 if(session.ReminderAt.HasValue&&DateTime.UtcNow>=session.ReminderAt.Value.ToUniversalTime()){session.ReminderAt=null;if(ReminderWindowOpen(session,DateTime.Now)&&DayType(DateTime.Today)!="休息")ShowReminder();changed=true;}
 if(changed){Save();RefreshTasks();}}
 void CommitQuick(){if(quick==null||string.IsNullOrWhiteSpace(quick.Text))return;string text=quick.Text.Trim();quick.Clear();var parsed=Parse(text);var matches=MatchingGoals(text,Today.Substring(0,7));data.Items.Add(new Item{Date=Today,Name=text,Numeric=parsed.Item4,Target=parsed.Item4?Math.Max(1,parsed.Item2):1,Unit=parsed.Item3,Kpi=matches.Count==1?matches[0].Name:"",Temporary=matches.Count!=1});Save();RefreshTasks();}
 void RefreshTasks(){list.Controls.Clear();if(desk!=null){desk.PlaceInput();desk.Invalidate();}if(TasksChanged!=null)TasksChanged();if(embedded!=null&&embedded.Visible&&!inlineActive)RenderEmbedded();}
 Control Row(Item i,int width){decimal done=Done(i);var row=new Panel{Width=width,Height=32,Margin=new Padding(1),BackColor=paper,BorderStyle=BorderStyle.None};var label=new Label{Text=RemainingTitle(i),Location=new Point(26,2),Size=new Size(width-106,27),ForeColor=ink,Font=new Font(Font.FontFamily,8,FontStyle.Bold),TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true}; row.Controls.Add(label);row.Paint+=(sender,args)=>{DeskTheme.Frame(args.Graphics,new Rectangle(0,0,row.Width,row.Height),paper,ink);TaskIcons.Draw(args.Graphics,i.Name,6,8,Done(i)>=i.Target,i.Temporary&&string.IsNullOrEmpty(i.Kpi));}; NumericUpDown pending=null;string[] symbols={"✓","○","×"};for(int n=0;n<3;n++){int index=n;var b=new TaskActionButton{Text=symbols[n]};b.Click+=(sender,args)=>{if(index==0){decimal remaining=pending==null?i.Target-Done(i):pending.Value;if(remaining>0)data.Entries.Add(new Entry{Item=i.Id,Date=Today,Amount=remaining});}else if(index==1){if(i.Numeric){decimal amount;if(!decimal.TryParse(Ask("本次新增完成量（剩余 "+Math.Max(0,i.Target-Done(i))+"）","0"),out amount)||amount<=0||amount>i.Target-Done(i))return;data.Entries.Add(new Entry{Item=i.Id,Date=Today,Amount=amount});}else{string note=Ask("填写简短进展",i.Note);if(note==null)return;i.Note=note;}}else {i.Deleted=true;}var parent=row.FindForm();Save();RefreshTasks();if(parent!=this&&parent!=null){parent.Close();OpenPage("未完");}};b.SetBounds(width-77+n*25,5,23,22);b.AccessibleName=new[]{"全部完成","部分完成","删除任务"}[n];row.Controls.Add(b);}return row;}
 string Ask(string title,string initial){return AskInline(title,initial);}
 Form Page(string title){var f=new PixelPage(title){Text="像素工作台 / "+title,Size=new Size(820,740),MinimumSize=new Size(650,500),StartPosition=FormStartPosition.CenterScreen,BackColor=paper,Font=Font};return f;}
 string DayType(DateTime d){string t;if(data.Days.TryGetValue(d.ToString("yyyy-MM-dd"),out t))return t;return d.DayOfWeek==DayOfWeek.Saturday||d.DayOfWeek==DayOfWeek.Sunday?"休息":"工作";}
 void OpenPage(string name){OpenEmbedded(name);}
