 var daily=data.Items.Where(i=>i.Date==active&&!i.Deleted).ToList();detailTitle.Text=DateTime.Parse(active).ToString("MM月dd日")+" · "+daily.Count+" 项任务";taskList.Items.Clear();
 foreach(var task in daily){decimal done=Done(task);taskList.Items.Add((done>=task.Target?"✓ ":done>0?"○ ":"· ")+task.Name+(task.Numeric?"  "+done+" / "+task.Target+task.Unit:done>=task.Target?"  已完成":task.Note==""?"  待完成":"  "+task.Note));}if(daily.Count==0)taskList.Items.Add("当天暂无任务");
