 f.Controls.Add(grid);f.Controls.Add(footer);f.Controls.Add(details);f.Controls.Add(month);TasksChanged+=draw;f.FormClosed+=(sender,e)=>TasksChanged-=draw;draw();f.Show();DeskTheme.Apply(f);taskList.ItemHeight=23;
