 void EditItem(Item i){string name=Ask("修改当天任务名称",i.Name);if(string.IsNullOrWhiteSpace(name))return;decimal target=i.Target;if(i.Numeric){decimal parsed;if(!decimal.TryParse(Ask("目标数量（不得低于已完成量）",i.Target.ToString()),out parsed)||parsed<=0||parsed<Done(i))return;target=parsed;}i.Name=name;i.Target=target;Save();}
 static Tuple<string,decimal,string,bool> Parse(string text){var m=Regex.Match(text,@"(?<n>\d+(?:\.\d+)?)\s*(?<u>篇|封|个|条|次|份|页|人|项)");decimal number;bool numeric=m.Success&&decimal.TryParse(m.Groups["n"].Value,out number);number=numeric?decimal.Parse(m.Groups["n"].Value):1;string name=numeric?text.Remove(m.Index,m.Length).Trim():text.Trim();name=Regex.Replace(name,@"^(今天|完成|发送|发布)\s*","");if(name=="")name=text;return Tuple.Create(name,number,numeric?m.Groups["u"].Value:"项",numeric);}
 void AddDialog(string text,string[] dates,Form owner){var p=Parse(text);using(var f=Page("确认任务")){f.Size=new Size(680,600);var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(15)};f.Controls.Add(flow);flow.Controls.Add(new Label{Text="每个选中日期分别添加；请检查识别结果",Width=550});var name=new TextBox{Text=p.Item1,Width=550};flow.Controls.Add(new Label{Text="任务名称"});flow.Controls.Add(name);var numeric=new CheckBox{Text="数量型任务",Checked=p.Item4,Width=250};flow.Controls.Add(numeric);var amount=new NumericUpDown{Minimum=1,Maximum=1000000,DecimalPlaces=2,Value=Math.Max(1,Math.Min(1000000,p.Item2)),Width=200};flow.Controls.Add(new Label{Text="每天目标数量"});flow.Controls.Add(amount);var unit=new TextBox{Text=p.Item3,Width=150};flow.Controls.Add(new Label{Text="单位"});flow.Controls.Add(unit);var kpi=new ComboBox{Width=350,DropDownStyle=ComboBoxStyle.DropDownList};kpi.Items.Add("不关联 KPI");foreach(var g in data.Goals.Where(g=>!g.Manual&&dates.Any(d=>d.StartsWith(g.Month))).Select(g=>g.Name).Distinct())kpi.Items.Add(g);kpi.SelectedIndex=0;for(int n=1;n<kpi.Items.Count;n++)if(text.IndexOf(kpi.Items[n].ToString(),StringComparison.OrdinalIgnoreCase)>=0)kpi.SelectedIndex=n;flow.Controls.Add(new Label{Text="关联 KPI"});flow.Controls.Add(kpi);flow.Controls.Add(new Label{Text="已选 "+dates.Length+" 天；数量按每天分别计算",Width=550});flow.Controls.Add(Button("确认添加",()=>{if(string.IsNullOrWhiteSpace(name.Text))return;foreach(string d in dates)data.Items.Add(new Item{Date=d,Name=name.Text.Trim(),Numeric=numeric.Checked,Target=numeric.Checked?amount.Value:1,Unit=numeric.Checked?unit.Text:"项",Kpi=kpi.SelectedIndex==0?"":kpi.Text});Save();RefreshTasks();f.Close();}));f.ShowDialog(owner);}}
