 static string KpiKey(string value){return Regex.Replace((value??"").Normalize(System.Text.NormalizationForm.FormKC).ToLowerInvariant(),@"[\s\p{P}\p{S}]","");}
 List<Goal> MatchingGoals(string name,string month){string key=KpiKey(name);return data.Goals.Where(g=>!g.Manual&&g.Month==month&&KpiKey(g.Name).Length>0&&key.Contains(KpiKey(g.Name))).ToList();}
 void ReconcileGoalLinks(){bool changed=false;foreach(var item in data.Items.Where(i=>string.IsNullOrEmpty(i.Kpi)&&!string.IsNullOrEmpty(i.Date))){var candidates=MatchingGoals(item.Name,item.Date.Substring(0,7));if(candidates.Count==1){item.Kpi=candidates[0].Name;item.Temporary=false;changed=true;}}if(changed)Save();}
 decimal Actual(Goal g){return g.Manual?g.Actual:g.Adjustment+data.Entries.Where(e=>e.Date.StartsWith(g.Month)&&data.Items.Any(i=>i.Id==e.Item&&i.Kpi==g.Name)).Sum(e=>e.Amount);}
 void Goals(){var f=Page("月度 KPI");var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(15)};f.Controls.Add(flow);var month=new PixelDatePicker{Format=DateTimePickerFormat.Custom,CustomFormat="yyyy-MM",ShowUpDown=true,Width=180};flow.Controls.Add(month);var rows=new FlowLayoutPanel{Width=750,Height=440,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};flow.Controls.Add(rows);Action draw=null;draw=()=>{rows.Controls.Clear();foreach(var g in data.Goals.Where(g=>g.Month==month.Value.ToString("yyyy-MM"))){var actual=Actual(g);var panel=new FlowLayoutPanel{Width=720,Height=105,Padding=new Padding(10),BorderStyle=BorderStyle.FixedSingle};panel.Controls.Add(new Label{Text=g.Name+"  "+actual+" / "+g.Target+"  ("+(g.Target>0?actual/g.Target*100:0).ToString("0.#")+"%)",Width=650,Height=24});panel.Controls.Add(new PixelProgress{Width=500,Height=18,Value=g.Target>0?(int)Math.Min(100,Math.Max(0,actual/g.Target*100)):0});panel.Controls.Add(Button("编辑",()=>{string raw=Ask("月目标",g.Target.ToString());decimal value;if(decimal.TryParse(raw,out value)&&value>0){g.Target=value;if(g.Manual){decimal a;if(decimal.TryParse(Ask("本月累计完成总数",g.Actual.ToString()),out a))g.Actual=a;}Save();draw();}}));rows.Controls.Add(panel);}};month.ValueChanged+=(s,e)=>draw();flow.Controls.Add(Button("新增目标",()=>{string n=Ask("KPI 名称","");if(string.IsNullOrWhiteSpace(n))return;string m=month.Value.ToString("yyyy-MM");if(data.Goals.Any(g=>g.Month==m&&g.Name==n)){MessageBox.Show("本月已有同名目标。");return;}decimal t;if(!decimal.TryParse(Ask("本月目标数量","80"),out t)||t<=0)return;bool manual=MessageBox.Show("是否为手动填写累计值的结果指标？\n例如 Profile、粉丝增长。","统计方式",MessageBoxButtons.YesNo)==DialogResult.Yes;data.Goals.Add(new Goal{Month=m,Name=n,Target=t,Manual=manual});Save();draw();}));draw();f.Show();}
 void Settings(){var f=Page("设置与备份");var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(20)};f.Controls.Add(flow);flow.Controls.Add(new Label{Text="数据仅保存在本机：\n"+Dir+"\n每天首次修改前自动备份。日历日期右键可设 CSA／调休。",Width=680,Height=115});flow.Controls.Add(Button("导出数据",()=>{using(var d=new SaveFileDialog{Filter="工作台数据|*.json",FileName="工作台-"+Today+".json"})if(d.ShowDialog()==DialogResult.OK){Save();File.Copy(FileName,d.FileName,true);}}));flow.Controls.Add(Button("恢复数据",()=>{using(var d=new OpenFileDialog{Filter="工作台数据|*.json"})if(d.ShowDialog()==DialogResult.OK){try{var restored=Json.Deserialize<Data>(File.ReadAllText(d.FileName));if(restored==null||restored.Items==null||restored.Entries==null||restored.Goals==null||restored.Sessions==null||restored.Days==null)throw new Exception("数据结构无效");if(MessageBox.Show("恢复将替换当前数据，继续吗？","恢复",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;Save();File.Copy(FileName,Path.Combine(Dir,"before-restore-"+DateTime.Now.Ticks+".json"));data=restored;Tick();Save();RefreshTasks();MessageBox.Show("恢复完成。");}catch(Exception e){MessageBox.Show("恢复失败："+e.Message);}}}));var startup=new CheckBox{Text="登录 Windows 后自动启动",Width=400};using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run"))startup.Checked=key!=null&&key.GetValue("PixelWorkbench")!=null;startup.CheckedChanged+=(s,e)=>{using(var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){if(startup.Checked)key.SetValue("PixelWorkbench","\""+Application.ExecutablePath+"\"");else key.DeleteValue("PixelWorkbench",false);}};flow.Controls.Add(startup);flow.Controls.Add(Button("备份目录",()=>System.Diagnostics.Process.Start(Dir)));f.Show();}
 static void SelfTest(){var p=Parse("完成3篇fb reels");if(p.Item1!="fb reels"||p.Item2!=3||!p.Item4)throw new Exception("parse failed");if(Parse("写匿名建议").Item4)throw new Exception("plain failed");var d=new Data();var i=new Item{Date="2026-11-19",Target=10,Kpi="邮件"};d.Items.Add(i);d.Entries.Add(new Entry{Item=i.Id,Date="2026-11-19",Amount=4});d.Entries.Add(new Entry{Item=i.Id,Date="2026-11-20",Amount=2});if(d.Entries.Sum(e=>e.Amount)!=6)throw new Exception("increment failed");i.Deleted=true;if(d.Entries.Sum(e=>e.Amount)!=6)throw new Exception("deletion failed");var copy=Json.Deserialize<Data>(Json.Serialize(d));if(copy.Items.Count!=1||copy.Entries.Sum(e=>e.Amount)!=6)throw new Exception("persistence failed");Console.WriteLine("PASS: parser, increments, retained history, JSON round-trip");}
